insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'odds-on-look-on', 'Odds On Look On', array['tipster']::listing_type[], 'Free Australian racing selections with an eye for each-way value.', 'John is a Sydney punter who posts free selections for the main Australian meetings on X, with a soft spot for each-way chances at bigger prices. Covers metropolitan cards across Sydney, Melbourne, Brisbane, Adelaide and Perth, plus quaddie picks and results.', 'https://x.com/Odds_On_Look_On', 'free'::pricing_model, null, array['racing']::text[], null, array['Free picks','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "Established account (about 5,600 followers, on X since 2022). Free tips only, no selling or bookmaker promotion seen. Low risk. His handle uses underscores; change the display name if he prefers it that way.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Odds On Look On')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/Odds_On_Look_On')) as v(platform,url) where l.slug = 'odds-on-look-on' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'boom-punting', 'Boom Punting', array['tipster','creator']::listing_type[], 'Rhys''s racing tips from Melbourne, with a weekly $100 challenge.', 'Rhys posts tips for Australian race meetings on X, with a strong lean towards Perth and Melbourne racing. Runs a weekly $100 challenge and community tipping comps, with extra content for Patreon members.', 'https://x.com/BoomPunting', 'freemium'::pricing_model, 'Free tips on X, with a paid Patreon', array['racing']::text[], null, array['Free picks','Paid picks','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "About 2,200 followers, on X since 2023. Check what the Patreon offers and costs, and confirm the Patreon link. No bookmaker promotion seen.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('Boom Punting')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/BoomPunting'),('Patreon','https://www.patreon.com/BoomPunting')) as v(platform,url) where l.slug = 'boom-punting' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'the-post-racing', 'The Post', array['tipster','community']::listing_type[], 'Data-led racing tips built on form, class, sectionals and market moves.', 'The Post publishes staked tips for Australian meetings, built from form, class, sectionals and live market analysis to find bets with positive expected value. Each meeting gets a review with units and strike rate, and the full service runs through Discord.', 'https://x.com/ThePostRacing', 'free'::pricing_model, 'Check whether the Discord is free or paid', array['racing']::text[], null, array['Free picks','Discord community','Publicly tracked record']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "New and small (joined July 2026, about 230 followers). Results posted after each meeting are his own figures; do not repeat them. Check whether the Discord is paid and update pricing. Australian flag is a best guess from the content.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('The Post')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/ThePostRacing'),('Discord','https://discord.gg/dWpWa5YPng')) as v(platform,url) where l.slug = 'the-post-racing' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
insert into listings (slug, name, types, tagline, bio, website_url, pricing, pricing_note, sports, category, features, status, attributes) select 'hd-aus-racing', 'HD Aus Racing', array['tipster']::listing_type[], 'Full-meeting tips and a daily best bet for Sydney and Melbourne racing.', 'H posts full-card tips for the main Sydney and Melbourne meetings on X, with a bet of the day, stakes in units and an honest tally of the week''s results, losing days included.', 'https://x.com/HDAusRacing', 'free'::pricing_model, null, array['racing']::text[], null, array['Free picks','Write-ups with reasoning','Daily content']::text[], 'draft'::publish_status, '{"starter": true, "vet_note": "About 1,800 followers, on X since 2024. His display name on X is just ''H'', so confirm what he wants the listing called. Posts results including losses, which is a good sign. No selling or bookmaker promotion seen. Australian flag is a best guess from the content.", "country": "AU"}'::jsonb where not exists (select 1 from listings where lower(name) = lower('HD Aus Racing')) on conflict (slug) do nothing;
insert into listing_links (listing_id, platform, url) select l.id, v.platform, v.url from listings l, (values ('X','https://x.com/HDAusRacing')) as v(platform,url) where l.slug = 'hd-aus-racing' and l.status = 'draft' and not exists (select 1 from listing_links k where k.listing_id = l.id);
